// Pregunta de respuesta múltiple escrita como objeto. Su clave tiene un defecto.
export const pregunta = {
  enunciado:
    "Una aplicación debe seguir disponible si falla un centro de datos y sus datos no pueden salir de la región. Selecciona DOS acciones que cumplan ambos requisitos.",
  seleccionar: 2,
  opciones: [
    {
      id: "a",
      texto: "Distribuir las instancias en varias zonas de disponibilidad de la región.",
      cumple: true,
      explicacion: "Cumple: las zonas no comparten puntos únicos de falla y los datos siguen en la región.",
    },
    {
      id: "b",
      texto: "Replicar la aplicación y los datos en otra región.",
      cumple: false,
      explicacion: "No cumple: la réplica saca los datos de la región, que es la restricción.",
    },
    {
      id: "c",
      texto: "Poner un balanceador de carga que reparta el tráfico entre instancias de zonas distintas.",
      cumple: true,
      explicacion: "Cumple: el tráfico sigue llegando a las instancias de otra zona si una falla.",
    },
    {
      id: "d",
      texto: "Usar instancias más grandes dentro de una sola zona de disponibilidad.",
      cumple: false,
      explicacion: "No cumple: sigue dependiendo de una sola zona, así que un fallo de la zona la detiene.",
    },
    {
      id: "e",
      texto: "Programar copias de seguridad semanales en la misma zona de disponibilidad.",
      cumple: false,
      explicacion: "No cumple: una copia en la misma zona no mantiene la aplicación en marcha si esa zona falla.",
    },
  ],
  correctas: ["a","c","d"],
};

