spec.code:
const ids = pregunta.opciones.map((opcion) => opcion.id);
for (const id of pregunta.correctas) {
  assert.ok(ids.includes(id), id + " no es una opción");
}

assert.strictEqual(pregunta.seleccionar, 2);
assert.ok(pregunta.enunciado.includes("DOS"));
assert.deepStrictEqual(pregunta.opciones.map((opcion) => [opcion.id, opcion.cumple]), [["a", true], ["b", false], ["c", true], ["d", false], ["e", false]]);
